import React, { useState, useEffect } from "react";
import { Menu, X, Search } from "lucide-react";
import { useNavigate, useLocation } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import { collection, getDocs, query, orderBy, limit } from "firebase/firestore";
import { db } from "../firebase";

export default function Navbar() {
  const [openMenu, setOpenMenu] = useState(false);
  const [latestEditions, setLatestEditions] = useState([]);

  const navigate = useNavigate();
  const location = useLocation();

  const navItems = [
    { name: "Home", path: "/" },
    { name: "My Space", path: "/myspace" },
    { name: "About", path: "/about" },
  ];

  const categories = [
    { name: "Cover Story", path: "/category/coverstory" },
    { name: "Interview", path: "/category/interview" },
    { name: "Story", path: "/category/story" },
    { name: "Poem", path: "/category/poem" },
    { name: "Review", path: "/category/review" },
    { name: "Zoom In", path: "/category/zoomin" },
    { name: "Article", path: "/category/article" },
    { name: "Standpoint", path: "/category/standpoint" },
    { name: "Exclusive", path: "/category/exclusive" },
    { name: "Lookout", path: "/category/lookout" },
    { name: "Festivities", path: "/category/festivities" },
    { name: "View In", path: "/category/viewin" },
  ];

  // Fetch latest 3 editions
  useEffect(() => {
    const fetchLatest = async () => {
      const q = query(
        collection(db, "editions"),
        orderBy("date", "desc"),
        limit(3)
      );
      const snap = await getDocs(q);
      setLatestEditions(
        snap.docs.map((doc) => ({ id: doc.id, ...doc.data() }))
      );
    };
    fetchLatest();
  }, []);

  return (
    <div className="fixed top-0 font-blinker left-0 w-full bg-white border-b shadow-sm z-50">
      {/* TOP BAR */}
      <div className="max-w-7xl mx-auto flex items-center justify-between px-4 py-3">
        {/* LEFT */}
        <div className="flex items-center gap-3">
          <button
            onClick={() => setOpenMenu(!openMenu)}
            className="p-2 hover:bg-gray-100 rounded-md"
          >
            {openMenu ? <X size={22} /> : <Menu size={22} />}
          </button>

          <button
            onClick={() => navigate("/search")}
            className="p-2 hover:bg-gray-100 rounded-md"
          >
            <Search size={20} />
          </button>
        </div>

        {/* LOGO */}
        <h1
          className="text-2xl md:text-3xl font-semibold cursor-pointer"
          onClick={() => navigate("/")}
        >
          The Guide
        </h1>

        {/* DESKTOP NAV */}
        <div className="hidden md:flex gap-6">
          {navItems.map((item) => (
            <button
              key={item.name}
              onClick={() => navigate(item.path)}
              className={`text-sm font-medium ${
                location.pathname === item.path
                  ? "text-red-600 border-b-2 border-red-600"
                  : "hover:text-gray-600"
              }`}
            >
              {item.name}
            </button>
          ))}
        </div>
      </div>

      {/* MEGA MENU */}
      <AnimatePresence>
        {openMenu && (
          <motion.div
            className="bg-white border-t shadow-xl"
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
          >
            <div className="max-w-7xl mx-auto px-6 py-8 grid grid-cols-1 md:grid-cols-3 gap-10">

              {/* LEFT — CATEGORIES */}
              <div className="md:col-span-2">
                <h2 className="text-xs font-semibold text-red-600 mb-4 uppercase">
                  Sections
                </h2>

                <div className="grid grid-cols-2 md:grid-cols-3 gap-y-3 text-sm">
                  {categories.map((cat) => (
                    <span
                      key={cat.name}
                      onClick={() => {
                        navigate(cat.path);
                        setOpenMenu(false);
                      }}
                      className="cursor-pointer hover:text-red-600"
                    >
                      {cat.name}
                    </span>
                  ))}
                </div>

                <div className="mt-6 flex gap-6 text-sm font-medium">
                  <span onClick={() => navigate("/")} className="cursor-pointer">
                    Home
                  </span>
                  <span onClick={() => navigate("/myspace")} className="cursor-pointer">
                    My Space
                  </span>
                  <span onClick={() => navigate("/about")} className="cursor-pointer">
                    About
                  </span>
                </div>
              </div>

              {/* RIGHT — LATEST GUIDES */}
              <div>
                <h2 className="text-xs font-semibold text-red-600 mb-4 uppercase">
                  Latest Guide
                </h2>

                {latestEditions.length === 3 && (
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">

                    {/* BIG LEFT */}
                    <div className="md:col-span-2">
                      <img
                        src={latestEditions[0].singlecover}
                        alt={latestEditions[0].title}
                        className="w-full h-56 md:h-full object-cover cursor-pointer"
                        onClick={() =>
                          navigate(`/edition/${latestEditions[0].id}`)
                        }
                      />
                    </div>

                    {/* RIGHT — TWO SMALL */}
                    <div className="grid grid-cols-2 md:grid-cols-1 gap-4">
                      {latestEditions.slice(0).map((ed) => (
                        <img
                          key={ed.id}
                          src={ed.singlecover}
                          alt={ed.title}
                          className="w-full h- object-cover cursor-pointer"
                          onClick={() => navigate(`/edition/${ed.id}`)}
                        />
                      ))}
                    </div>
                  </div>
                )}
              </div>

            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
